import java.util.*;

public class Main {
    void invertedLeftHalfPyramid(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append(" ".repeat(i - 1)).append("*".repeat(n - i + 1));  // build every row directly
            if (i < n) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                        // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.invertedLeftHalfPyramid(4);
    }
}

